import{z as i,x as s,o as n,c as C,q as l,j as A,D as t,d as e,s as r,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"视觉 token 预算","description":"","frontmatter":{"title":"视觉 token 预算","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mm-visual-token-budget.md","filePath":"llm/mm-visual-token-budget.md","lastUpdated":1791063341000}'),m={name:"llm/mm-visual-token-budget.md"};function p(d,E,k,c,h,D){const o=s("Mermaid");return n(),C("div",null,[E[2]||(E[2]=l('<h1 id="视觉-token-预算" tabindex="-1">视觉 token 预算 <a class="header-anchor" href="#视觉-token-预算" aria-label="Permalink to &quot;视觉 token 预算&quot;">​</a></h1><div class="epigraph"><p>视觉 token 不是免费的像素，是按上下文计价的注意力；预算不封顶，窗口和账单都会被一张 8K 截图吃光。</p><footer>—— 据 Qwen2.5-VL Technical Report 的动态分辨率与 patch merge 机制、视觉 token 压缩文献整理</footer></div><p><a href="/llm/mm-image-preprocess-batching">上一课</a>把预处理组织成分档批处理，但档位表的另一头连着语言模型：档定多高，进入 prefill 的视觉 token 就多长。缺口是预算本身——一张图该折算成多少 token、上限谁说了算、砍预算时丢的是哪种信息。本课把视觉 token 预算写成服务端的一等旋钮：怎么计价、怎么封顶、怎么按请求分配。视频的时间维预算留到下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>计价公式是确定的。14px 一 patch，\\(2\\times2\\) merge 后每四格折一个 token（见 <a href="/llm/qwen-vl-patch-merge">patch merge</a>），一张 \\(H\\times W\\) 的图占 \\(\\frac{H}{28}\\times\\frac{W}{28}\\) 个语言模型 token。问题在于用户不知道也不关心这个公式：一张 7680×4320 的截图按公式是近八万 token，不设上限，一次请求就能打穿上下文窗口、把 prefill 拖进秒级、给 KV 留下几百 MB 的账（账目细算见<a href="/llm/mm-multimodal-kv">多模态 KV 管理</a>）。预算缺位不是报错，而是延迟与成本被最重的请求定形。</p><p>预算也不只是封顶线。聊天里配图的合理预算与 OCR 合同页的合理预算差一个量级：前者几百 token 足够，后者砍到几百 token 就是让模型猜小字。预算是按场景定价的资源配置，不是单一常数。</p><p><span class="marginnote">可以把视觉 token 理解成「按像素折算的注意力门票」：一张图的 token 数和一段文字的 token 数在模型眼里同价，都占上下文、都进 KV、都参与注意力。所谓预算，就是给图买的门票数设上限——不设限，一张 8K 截图能把全场座位占光。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>服务端把预算拆成三层，各是独立可配的硬闸。<strong>图级</strong>：预处理阶段按档位表缩放，等比压到预算内；这是最高优先级闸，任何请求不得突破。<strong>请求级</strong>：单请求所有图的 token 总和封顶，超了按序压缩，防止十张小图叠成大账。<strong>会话级</strong>：多轮里历史图像 token 的存留策略——引用过的图保留全预算，翻篇的图降采样或只留摘要，会话越长这条越要紧。三层都实现为<a href="/llm/mm-image-preprocess-batching">预处理档位表</a>的约束，预算执行不新增关键路径。</p><p><span class="marginnote">十张小图为什么需要请求级闸？单张 400 token 看着温和，十张就是 4000 token——再配一段长提问，上下文与 prefill 时间立刻翻倍。每张图都在预算内、合起来却超支，和「每道菜都不贵、账单很贵」一个道理。</span></p><p>预算同时要可感知。响应里返回实际消耗的视觉 token 数，超限被压缩时明确告知：用户看到「图被降分辨率」与看到「模型看不清小字」，是可归因与不可归因的区别。对延迟敏感或低优先级请求，调度器可以按<a href="/llm/sch-priority-fairness">优先级</a>动态压预算——预算因此成了过载时的第一道降级阀。</p><p><span class="marginnote">一张 1344×896 的文档页是 \\(\\frac{1344}{28}\\times\\frac{896}{28}=48\\times32=1536\\) 个视觉 token，接近一千五百汉字的上下文占用；而 OCR 可读的小字往往就住在最高那档预算里。</span></p>',12)),(n(),A(B,null,{default:t(()=>[r(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E5%8E%9F%E5%9B%BE%20H%C3%97W%22%5D%20--%3E%20CALC%7B%22%E6%8A%98%E7%AE%97%20token%20%E6%95%B0%22%7D%0A%20%20CALC%20--%3E%7C%22%E8%B6%85%E5%9B%BE%E7%BA%A7%E9%A2%84%E7%AE%97%22%7C%20SCALE%5B%22%E7%AD%89%E6%AF%94%E7%BC%A9%E6%94%BE%E5%B0%81%E9%A1%B6%22%5D%0A%20%20CALC%20--%3E%7C%22%E6%9C%AA%E8%B6%85%22%7C%20MERGE%0A%20%20SCALE%20--%3E%20MERGE%5B%22%E5%88%87%20patch%20%E4%B8%8E%202%C3%972%20merge%22%5D%0A%20%20MERGE%20--%3E%20SUM%7B%22%E8%AF%B7%E6%B1%82%E7%B4%AF%E8%AE%A1%E8%B6%85%E9%A2%84%E7%AE%97%3F%22%7D%0A%20%20SUM%20--%3E%7C%E6%98%AF%7C%20COMP%5B%22%E6%8C%89%E5%BA%8F%E5%8E%8B%E7%BC%A9%E5%90%8E%E7%BB%AD%E5%9B%BE%22%5D%0A%20%20SUM%20--%3E%7C%E5%90%A6%7C%20CTX%0A%20%20COMP%20--%3E%20CTX%5B%22%E8%A7%86%E8%A7%89%20token%20%E6%B5%81%E6%8B%BC%E5%85%A5%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20CTX%20--%3E%20REP%5B%22%E5%93%8D%E5%BA%94%E5%9B%9E%E6%89%A7%EF%BC%9A%E5%AE%9E%E9%99%85%20token%20%E6%95%B0%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("预算削减信息的方式有两种，性质不同。"),a("strong",null,"编码前缩放"),e("丢分辨率：等比缩到预算内，全局结构保留，最小字体与细线条先消失——这是预处理侧的闸，成本为零但不可逆。"),a("strong",null,"编码后剪枝"),e("丢冗余：按注意力或重要性分数把低贡献视觉 token 丢弃（"),a("a",{href:"/llm/vision-token-compression"},"视觉 token 压缩"),e("），分辨率不动，丢的是模型觉得冗余的部分——保留了看清的能力，代价是多付一次完整编码。两条线的取舍是场景定价的物理依据：聊天流量走缩放即可，文档与图表流量值得付剪枝的钱。")],-1)),(n(),A(B,null,{default:t(()=>[r(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E9%99%8D%E9%A2%84%E7%AE%97%E8%B5%B0%E5%93%AA%E6%9D%A1%E8%B7%AF%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%BC%96%E7%A0%81%E5%89%8D%E7%BC%A9%E6%94%BE%22%7C%20SC%5B%22%E7%AD%89%E6%AF%94%E7%BC%A9%E5%88%B0%E9%A2%84%E7%AE%97%E5%86%85%E5%86%8D%E7%BC%96%E7%A0%81%22%5D%0A%20%20SC%20--%3E%20SCL%5B%22%E4%B8%A2%EF%BC%9A%E6%9C%80%E5%B0%8F%E5%AD%97%E4%BD%93%E4%B8%8E%E7%BB%86%E7%BA%BF%E6%9D%A1%22%5D%0A%20%20SC%20--%3E%20SCP%5B%22%E6%88%90%E6%9C%AC%EF%BC%9A%E9%9B%B6%EF%BC%8C%E9%A2%84%E5%A4%84%E7%90%86%E9%A1%BA%E5%B8%A6%E5%AE%8C%E6%88%90%22%5D%0A%20%20SC%20--%3E%20SCN%5B%22%E5%85%A8%E5%B1%80%E7%BB%93%E6%9E%84%E4%BF%9D%E7%95%99%EF%BC%8C%E4%B8%8D%E5%8F%AF%E9%80%86%22%5D%0A%20%20Q%20--%3E%7C%22%E7%BC%96%E7%A0%81%E5%90%8E%E5%89%AA%E6%9E%9D%22%7C%20PR%5B%22%E5%85%A8%E5%88%86%E8%BE%A8%E7%8E%87%E7%BC%96%E7%A0%81%E5%90%8E%E6%8C%89%E9%87%8D%E8%A6%81%E6%80%A7%E4%B8%A2%E5%BC%83%22%5D%0A%20%20PR%20--%3E%20PRL%5B%22%E4%B8%A2%EF%BC%9A%E6%A8%A1%E5%9E%8B%E5%88%A4%E6%96%AD%E7%9A%84%E5%86%97%E4%BD%99%20token%22%5D%0A%20%20PR%20--%3E%20PRP%5B%22%E6%88%90%E6%9C%AC%EF%BC%9A%E5%A4%9A%E4%BB%98%E4%B8%80%E6%AC%A1%E5%AE%8C%E6%95%B4%E7%BC%96%E7%A0%81%22%5D%0A%20%20PR%20--%3E%20PRN%5B%22%E7%9C%8B%E6%B8%85%E7%9A%84%E8%83%BD%E5%8A%9B%E4%BF%9D%E7%95%99%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p>预算乘进三本账。延迟账：prefill 时间随视觉 token 数线性走，预算上限即首 token 延迟上限。KV 账：每 token 的 KV 字节固定，预算直接决定单请求 KV 占用，进而决定<a href="/llm/sch-continuous-batching-deep">连续批处理</a>的并发水位。质量账：预算低于任务信息量时，模型不是报错而是用语言先验补图——预算压得越低，幻觉越像真话。三本账都随预算单调，说明预算是容量规划的原生输入，不是事后调的成本参数。</p><p><span class="marginnote">常见误区：以为预算不够时模型会「老实说看不清」。实际它多半用语言先验补图——见过一万张白杯子，就把糊掉的杯子「脑补」成白的。答案越通顺越像真的，错了反而更难发现，这是预算压太低的隐性代价。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>预算对任务不对称：OCR、细图表、UI 截图的高信息密度区恰在最高预算档，压预算先死的是它们（<a href="/llm/ocr-vlm">OCR 实践</a>），而「图里有什么」类任务在低预算下几乎无损。按场景配预算因此要靠请求路由，不能靠全局常数。其次，预算改变答案而不改变置信度：同一问题高预算答对、低预算答错，模型两边的语气一样肯定，评测必须把预算当实验变量钉住，否则结论随默认值漂移。最后，预算管不了精度之外的事——遮挡、模糊、离屏内容不因预算提高而回来，向用户解释能力边界时不要拿预算当挡箭牌。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>视觉 token 计价是 \\(\\frac{H}{28}\\times\\frac{W}{28}\\)，与文本同价进注意力与 KV，必须显式封顶。</li><li>三层预算：图级缩放闸、请求级总量闸、会话级历史存留策略，全部落在预处理档位表上。</li><li>编码前缩放丢分辨率、编码后剪枝丢冗余，场景按此定价；OCR 类任务吃最高档。</li><li>预算乘进延迟、KV、质量三本账，是容量规划输入与过载降级的第一道阀。</li><li>超限要回执、评测要钉预算变量；低预算下模型用语言先验补图，幻觉更难辨。</li><li>出处：据 Qwen2.5-VL Technical Report（arXiv:2502.13923）的动态分辨率口径与视觉 token 压缩文献整理。</li></ul>',6))])}const g=i(m,[["render",p]]);export{u as __pageData,g as default};
